# Згенеровано Terraform (модуль lb). Активне середовище: blue
events {}

http {
  # Вбудований DNS Docker: ім'я app-blue повертає адреси всіх реплік групи.
  resolver 127.0.0.11 valid=5s ipv6=off;
  access_log /dev/stdout;

  server {
    listen 80;

    location = /lb/active {
      default_type text/plain;
      return 200 "blue\n";
    }

    location / {
      set $backend "http://app-blue:8080";
      proxy_pass $backend;
      proxy_set_header Host $host;
      proxy_next_upstream error timeout http_502 http_503;
      proxy_connect_timeout 2s;
    }
  }
}

